function o2_label($en,$da,$ps=null){return __t($en,$da,$ps??$da);}
function o2_event_label($action){$key=str_replace('Office 2: ','',$action);$names=['bootstrap'=>['Initial account setup','آماده‌سازی حساب اولیه'],'step_up'=>['Office access verified','تأیید دسترسی دفتر دو'],'create_user'=>['User created','ایجاد کاربر'],'edit_user'=>['User profile or role updated','تغییر مشخصات یا نقش'],'account_state'=>['Account status changed','تغییر وضعیت حساب'],'reset_password'=>['Temporary password assigned','تعیین رمز موقت'],'save_permissions'=>['User permissions updated','تغییر مجوزهای کاربر'],'subscription'=>['Subscription updated','به‌روزرسانی اشتراک'],'save_ai'=>['Advisor allowance updated','تغییر سهمیهٔ مشاور'],'reset_ai'=>['Advisor allowance reset','آزادسازی سهمیهٔ مشاور'],'toggle_feature_lock'=>['Global feature updated','تغییر قابلیت عمومی'],'bulk_lock_features'=>['Global feature batch updated','تغییر گروهی قابلیت‌ها'],'change_master_pin'=>['Secondary credential changed','تغییر رمز ثانویه'],'save_system_theme'=>['Default theme updated','تغییر تم پیش‌فرض'],'save_settings'=>['Invoice studio updated','تغییر استودیوی بل'],'reset_initial_setup'=>['Setup marker reset','بازنشانی علامت راه‌اندازی'],'lock_panel'=>['Office session closed','خروج از دفتر دو'],'factory_reset_database'=>['Business data reset with recovery','بازنشانی داده با بکاپ بازیابی']];return isset($names[$key])?o2_label(...$names[$key]):$action;}
function o2_form($action,$id=0){echo '<form method="post" class="office2-form" data-office-action="'.sanitize($action).'">'.csrf_field().'<input type="hidden" name="action" value="'.sanitize($action).'">';if($id)echo '<input type="hidden" name="user_id" value="'.(int)$id.'">';}
function o2_input($name,$label,$value='',$type='text',$required=false){$id='o2field_'.bin2hex(random_bytes(4));echo '<div class="form-group"><label class="form-label" for="'.$id.'">'.sanitize($label).'</label><input class="form-control" id="'.$id.'" name="'.sanitize($name).'" type="'.$type.'" value="'.sanitize($type==='password'?'':$value??'').'"'.($required?' required':'').(in_array($name,['username','fullname'],true)?' data-sensitive':'').($type==='password'?' data-sensitive autocomplete="'.($name==='current_password'?'current-password':'new-password').'" maxlength="72"':($type==='number'?' min="0" max="1000000" step="1"':'')).'></div>';}
function o2_textarea($name,$label,$value=''){$id='o2field_'.bin2hex(random_bytes(4));echo '<div class="form-group"><label class="form-label" for="'.$id.'">'.sanitize($label).'</label><textarea class="form-control" rows="3" id="'.$id.'" name="'.sanitize($name).'">'.sanitize($value).'</textarea></div>';}
function o2_select($name,$label,$options,$selected){$id='o2field_'.bin2hex(random_bytes(4));echo '<div class="form-group"><label class="form-label" for="'.$id.'">'.sanitize($label).'</label><select class="form-control" id="'.$id.'" name="'.sanitize($name).'">';foreach($options as $value=>$text)echo '<option value="'.sanitize($value).'"'.((string)$value===(string)$selected?' selected':'').'>'.sanitize($text).'</option>';echo '</select></div>';}
function o2_check($name,$label,$checked){echo '<label class="office2-check"><input type="hidden" name="'.sanitize($name).'" value="0"><input type="checkbox" name="'.sanitize($name).'" value="1"'.($checked?' checked':'').'><span>'.sanitize($label).'</span></label>';}
function o2_submit($text=null,$danger=false){echo '<button class="btn '.($danger?'btn-danger':'btn-primary').'" type="submit">'.sanitize($text??o2_label('Save changes','ذخیرهٔ تغییرات','بدلونونه خوندي کړئ')).'</button></form>';}
function o2_reauth(){o2_input('current_password',o2_label('Your current administrator password','رمز فعلی حساب مدیر','د مدیر حساب اوسنی رمز'),'','password',true);}
function o2_role_labels(){return array_combine(office2_roles(),array_map(fn($r)=>match($r){'superadmin','super_admin'=>o2_label('Super Admin','سوپر ادمین','سوپر مدیر'),'admin'=>o2_label('Administrator','مدیر','مدیر'),default=>o2_label('Staff','کارمند','کارکوونکی').' · '.$r},office2_roles()));}
